    try:
        x = next(it)
    except StopIteration:
        break
    print(x)

class Countdown:
    def __init__(self, n):
        self.n = n
    def __iter__(self):
        return self
    def __next__(self):
        if self.n <= 0:
            raise StopIteration
        self.n -= 1
        return self.n + 1

print(list(Countdown(3)))

class Repeat:
    def __init__(self, n):
        self.n = n
    def __iter__(self):
        return iter(range(self.n))      # a new one each time

r = Repeat(3)
print(list(r), list(r))

class Fib:
    def __init__(self):
        self.a, self.b = 0, 1
    def __iter__(self):
        return self
    def __next__(self):
        self.a, self.b = self.b, self.a + self.b
        return self.a

for i, x in enumerate(Fib()):
    if i == 8:
        break
    print(x, end=" ")

